89	/* handles CDC Ethernet and many other network "bulk data" interfaces */
90	int usbnet_get_endpoints(struct usbnet *dev, struct usb_interface *intf)
91	{
92		int				tmp;
93		struct usb_host_interface	*alt = NULL;
94		struct usb_host_endpoint	*in = NULL, *out = NULL;
95		struct usb_host_endpoint	*status = NULL;
96	
97		for (tmp = 0; tmp < intf->num_altsetting; tmp++) {
98			unsigned	ep;
99	
100			in = out = status = NULL;
101			alt = intf->altsetting + tmp;
102	
103			/* take the first altsetting with in-bulk + out-bulk;
104			 * remember any status endpoint, just in case;
105			 * ignore other endpoints and altsettings.
106			 */
107			for (ep = 0; ep < alt->desc.bNumEndpoints; ep++) {
108				struct usb_host_endpoint	*e;
109				int				intr = 0;
110	
111				e = alt->endpoint + ep;
112	
113				/* ignore endpoints which cannot transfer data */
114				if (!usb_endpoint_maxp(&e->desc))
115					continue;
116	
117				switch (e->desc.bmAttributes) {
118				case USB_ENDPOINT_XFER_INT:
119					if (!usb_endpoint_dir_in(&e->desc))
120						continue;
121					intr = 1;
122					fallthrough;
123				case USB_ENDPOINT_XFER_BULK:
124					break;
125				default:
126					continue;
127				}
128				if (usb_endpoint_dir_in(&e->desc)) {
129					if (!intr && !in)
130						in = e;
131					else if (intr && !status)
132						status = e;
133				} else {
134					if (!out)
135						out = e;
136				}
137			}
138			if (in && out)
139				break;
140		}
141		if (!alt || !in || !out)
142			return -EINVAL;
143	
144		if (alt->desc.bAlternateSetting != 0 ||
145		    !(dev->driver_info->flags & FLAG_NO_SETINT)) {
146			tmp = usb_set_interface(dev->udev, alt->desc.bInterfaceNumber,
147						alt->desc.bAlternateSetting);
148			if (tmp < 0)
149				return tmp;
150		}
151	
152		dev->in = usb_rcvbulkpipe(dev->udev,
153					  in->desc.bEndpointAddress & USB_ENDPOINT_NUMBER_MASK);
154		dev->out = usb_sndbulkpipe(dev->udev,
155					   out->desc.bEndpointAddress & USB_ENDPOINT_NUMBER_MASK);
156		dev->status = status;
157		return 0;
158	}
159	EXPORT_SYMBOL_GPL(usbnet_get_endpoints);
