161	int usbnet_get_ethernet_addr(struct usbnet *dev, int iMACAddress)
162	{
163		u8		addr[ETH_ALEN];
164		int 		tmp = -1, ret;
165		unsigned char	buf [13];
166	
167		ret = usb_string(dev->udev, iMACAddress, buf, sizeof(buf));
168		if (ret == 12)
169			tmp = hex2bin(addr, buf, 6);
170		if (tmp < 0) {
171			dev_dbg(&dev->udev->dev,
172				"bad MAC string %d fetch, %d\n", iMACAddress, tmp);
173			if (ret >= 0)
174				ret = -EINVAL;
175			return ret;
176		}
177		eth_hw_addr_set(dev->net, addr);
178		return 0;
179	}
180	EXPORT_SYMBOL_GPL(usbnet_get_ethernet_addr);
