182	static bool usbnet_needs_usb_name_format(struct usbnet *dev, struct net_device *net)
183	{
184		/* Point to point devices which don't have a real MAC address
185		 * (or report a fake local one) have historically used the usb%d
186		 * naming. Preserve this..
187		 */
